  Item_10095_Name = {
    Text = "স্মৃতি প্রতিলিপি"
  },
  Item_10096_Desc = {
    Text = "অজানা যে জ্ঞান, তা আমাদের উপর বর্ষিত হোক।\nফেলিন কবিতা সমিতির এক বিশেষ ফিল্ম, মানব-চেতনার প্রতিলিপি ধারণের উপযোগী।\nআল্ট্রা রাজ্য জাগরণকারী সত্তাদের শিক্ষার জন্য ব্যবহৃত এক উপাদান।"
