  Item_10097_Name = {
    Text = "খাটো সামুদ্রিক লিলি"
  },
  Item_10098_Desc = {
    Text = "জেনকিন তার ইঁদুর সঙ্গী ব্রাউনের মতোই দ্রুত আর ধরাছোঁয়ার বাইরে।\nআল্ট্রা লিপের মাধ্যমে প্রচণ্ড ক্ষতি দাও\nপরিস্থিতি অনুযায়ী মানিয়ে নেওয়া ক্ষতি-দানের ক্ষমতা"
