  Item_133766_Desc = {
    Text = "আত্মার অনুরণনের বস্তু, এখন শুধু রূপরেখার খণ্ডাংশ অবশিষ্ট। বিভিন্ন স্থানে ছড়িয়ে পড়া আশার সমন্বয় বাস্তবতা ভেদ করে বিবর্ধন আনুক।\nএটি 「রসায়নশালা」-এ 「আত্মা প্রত্যাবর্তন কোর」 তৈরি করতে ব্যবহার করা যাবে।"
