  Item_140407_Desc = {
    Text = "মিসাগার্ড দ্বারা নিয়মিত পরিচালিত অনুনাদ কম্পাঙ্ক ক্রমাঙ্কন, সিলভার কোর সংকেতের সিঙ্ক্রোনাইজড স্থিতিশীলতা বজায় রাখতে ব্যবহৃত।"
