  Item_141173_Name = {
    Text = "বিশাল 「শিকার」"
  },
  Item_141174_Desc = {
    Text = "এই পসি নোট করার পরে, দল গঠনের সময় পসি দক্ষতা নির্বাচন করা যাবে:「ফাঁপা মানুষ」।\n\nচলো তোমার এই জীবনে যা অভিজ্ঞতা হয়েছে তার গল্প বলি, এটি আর কোনো প্রতিধ্বনি পাবে না।\nযেন সমুদ্রের জল গভীর খাদে ঢেলে দেওয়া হয়, তারপর চিরকালের জন্য এখানেই থেকে যায়।"
  },
