  Item_22164_Desc = {
    Text = "নির্দেশনা মেনে চলুন এবং অতিরিক্ত সেবন এড়িয়ে চলুন।\nনসিস ইলিক্সিরে ভরা এক সরবরাহ বাক্স, যা মিশনে থাকা রক্ষকদের সহায়তা প্রদান করে।"
