  Item_22168_Desc = {
    Text = "মাসিক ছোট ছোট আনন্দ।\nপর্যাপ্ত পরিমাণ নসিস ইলিক্সির সম্বলিত একটি সরবরাহ প্যাক, যা মিশনে থাকা রক্ষকদের সহায়তা করে।"
