  Item_25219_Desc = {
    Text = "তারা কালো পুকুরে বিক্ষিপ্ত, সেই পবিত্র ও মহামুহূর্তের জন্য আকুল।\nমিথাগের গভীর থেকে আসা রহস্যময় খণ্ডাংশ। জ্ঞানের আদিসার-এ সংশ্লেষ করা যায়।"
