  Item_68419_Desc = {
    Text = "দীর্ঘ সময়ের প্যাসেজে, এই শোক একদিন মসৃণ হয়ে মিলিয়ে যাবে।\nদিব্য সার্বভৌমের অনুভূতিগুলো চেতনার মাত্রায় দাগ কেটে যায়, যা 「শোকাবহ অতল」-এ সামগ্রী বিনিময়ের জন্য ব্যবহৃত হয়।"
