  Item_73469_Desc = {
    Text = "এই কার্ডটা ট্র্যাফেজে এমন প্রভাব দেখাচ্ছে কেন! একেবারেই মেনে নেওয়া যায় না! আরেকটা ম্যাচ! পরেরবার আমি অবশ্যই জিতব!"
