  Item_77877_Desc = {
    Text = "অ্যালিমাস ও শক্তি উৎপাদন বৃদ্ধি করে, এবং অন্য জাগরণকারীদের পরবর্তী এক্সাল্টকেও শক্তিশালী করে। এক্সাল্ট মুক্ত করার সময়, গ্রাস প্রভাব সক্রিয় করা ক্যারো রিয়েল্মের জাগরণকারীরা প্রচুর অ্যালিমাসও পুনরুদ্ধার করবে।"
