  Item_78732_Name = {
    Text = "অন্ধকার স্রোতের পতঙ্গধ্বনি·সময়সীমিত প্রি-অর্ডার"
  },
  Item_78758_Desc = {
    Text = "এক প্রাচীন ইচ্ছার হারিয়ে যাওয়া চেতনা। এক রহস্যময় আচার অনুষ্ঠানের মাধ্যমে মিথাগ জাগরণকারীদের চেতনাকে আত্মজাগরণ করায়, আর আত্মজাগৃত জাগরণকারী স্থায়ী শক্তিবৃদ্ধি লাভ করে।\nতুলু: দেবরাজের নকল কপি প্রাপ্ত হলে রূপান্তরিত হবে। তুলু: দেবরাজের আত্মজাগরণ সক্রিয় হবে।"
  },
