  Item_90040_Desc = {
    Text = "পুরু, মজবুত হার্ডকভার বাঁধাইয়ে আবদ্ধ একগুচ্ছ গ্রন্থ, যার বিষয়বস্তু কালজয়ী, আর অক্ষরবিন্যাসে আছে পরিশীলিত সৌন্দর্য—যে কোনো বইপ্রেমীর তাকের জন্য এক নিখুঁত সংযোজন।"
