  Item_94440_Name = {
    Text = "মুশেট"
  },
  Item_94441_Desc = {
    Text = "এক প্রাচীন ইচ্ছার হারিয়ে যাওয়া চেতনা। এক রহস্যময় আচার অনুষ্ঠানের মাধ্যমে মিথাগ জাগরণকারীদের চেতনাকে আত্মজাগরণ করায়, আর আত্মজাগৃত জাগরণকারী স্থায়ী শক্তিবৃদ্ধি লাভ করে।\nমুশেটের নকল কপি প্রাপ্ত হলে রূপান্তরিত হবে। মুশেটের আত্মজাগরণ সক্রিয় হবে।"
  },
  Item_94441_Name = {
    Text = "শার্ড: মুশেট"
  },
  Item_94441_StoryDesc = {
    Text = "ডুপ্লিকেট মুশেট প্রাপ্ত হলে রূপান্তরিত হবে। মুশেটের আত্মজাগরণ সক্রিয় করে।"
  },
  Item_94442_Desc = {
