  Item_9866_Desc = {
    Text = "হ্যাঁ, সবকিছুই পাতিত করা যায়।\nতোমার প্রবৃত্তি, তোমার যুক্তি, এমনকি তোমার আত্মা...\nশেষে তুমি দেখবে, তুমি তাদের থেকে মোটেও আলাদা নও।\nঅ্যাকুওর জাগরণকারীদের শিক্ষণ প্রক্রিয়ায় ব্যবহৃত এক উপাদান।"
